/* Canonical server state is projected into the existing board's local-player view. */
(function(root){'use strict';
function project(state,seat){const s=JSON.parse(JSON.stringify(state));if(seat!==1)return s;
 const walk=o=>{if(!o||typeof o!=='object')return;for(const [k,v] of Object.entries(o)){if(k==='owner'&&(v===0||v===1))o[k]=1-v;else if(k==='text'&&typeof v==='string')o[k]=v.replace(/天辉|夜魇/g,x=>x==='天辉'?'夜魇':'天辉');else walk(v);}};walk(s);
 for(const k of ['players','deckSpecs'])if(s[k])s[k].reverse();
 for(const l of s.lanes)for(const k of ['towers','mana','manaBase','improvements'])l[k].reverse();
 for(const k of ['turn','initiative','winner'])if(s[k]===0||s[k]===1)s[k]=1-s[k];return s;
}
root.ArtifactOnlineProjection={project};if(typeof module!=='undefined'){module.exports={project};return;}
const watching=new URLSearchParams(location.search).get('spectate')==='1';
if(watching)document.body.classList.add('spectator');
const net=root.ArtifactOnline,esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let snapshot,app,pending=null,queue=[],draining=false,seen=-1,connected=false,inFlight=false,resuming=false;
const game=new ArtifactEngine.Game(ARTIFACT_CARDS);
for(const [method,action,args] of [ ['play','play',(p,handId,targets)=>({handId,targets})],['activate','activate',(p,sourceId,key,targets)=>({sourceId,key,targets})],['pass','pass',()=>({})],['buy','buy',(p,slot)=>({slot})],['hold','hold',()=>({})]])game[method]=(...v)=>{if(watching)throw Error('观战模式无法操作对局');if(pending)throw Error('正在提交上一行动');if(!connected)throw Error('连接中断，正在重连');pending={action,args:args(...v)};};
function request(action,args={}){if(watching){app?.onlineError('观战模式无法操作对局');return;}if(inFlight){app?.onlineError('上一行动正在确认，请稍候');return;}if(!connected){app?.onlineError('连接中断，正在重连；对局已保存');return;}inFlight=true;net.command(action,args).catch(e=>app?.onlineError(e.message)).finally(()=>{inFlight=false;});}
function accept(next){snapshot=next;if(!next.state&&watching){renderWaiting(next);return;}if(!next.state){location.replace('online.html?code='+encodeURIComponent(next.code));return;}if(next.revision<=seen){if(resuming){resuming=false;queue.push({state:project(next.state,next.seat),animate:false});drain();}else app?.onlineStatus();return;}const first=seen<0||resuming;resuming=false;seen=next.revision;queue.push({state:project(next.state,next.seat),animate:!first});drain();}
async function drain(){if(draining||!app)return;draining=true;while(queue.length){while(app.ui.busy)await new Promise(r=>setTimeout(r,40));const next=queue.shift();app.receiveOnline(next.state,next.animate);}draining=false;}
const bridge=root.ArtifactOnlineBridge={game,isSpectator:()=>watching,
 flush(){if(!pending)return false;const cmd=pending;pending=null;app.ui.selection=null;request(cmd.action,cmd.args);return true;},
 deploymentLocked(){return watching||!!snapshot?.deployReady?.[snapshot.seat];},
 mount(a){app=a;net.subscribe(accept);const latest=net.getSnapshot();if(latest){snapshot=latest;if(latest.state&&latest.revision>seen){game.s=project(latest.state,latest.seat);game.s.events=[];seen=latest.revision;}}connected=net.getStatus()==='connected';net.onStatus(status=>{if(status!=='connected')resuming=true;const changed=connected!==(status==='connected');connected=status==='connected';if(changed)app.onlineStatus();});net.onError(e=>app.onlineError(e.message||String(e)));drain();},
 header(){return `<header class="topbar"><a class="wordmark" href="online.html">◈ ${watching?'实时观战':'联机对战'}</a><nav><a href="online.html">返回房间</a><span>匹配码 ${esc(snapshot.code)}</span></nav><div class="header-tools"><button class="icon-button" data-action="sound" aria-label="切换声音">♫</button><button class="icon-button" data-action="settings" aria-label="设置">⚙</button><button data-action="log">战斗记录</button></div></header>`;},
 status(){if(watching)return `<div class="online-battle-status" role="status">${connected?'实时观战 · 天辉视角':'观战连接中断 · 正在重连'} · ${game.s.phase==='shop'?'双方购物中':game.s.phase==='deploy'?'双方规划分路中 · 确认前不可见':'双方手牌保密，可查看棋盘与战斗记录'}</div>`;const seat=snapshot.seat,op=snapshot.players[1-seat];let message=net.getStatus()==='replaced'?'此席位已在另一个页面打开 · 请在新页面继续':!connected?'连接中断 · 正在自动重连，进度已保存':!op.connected?'对方暂时离线 · 可等待对方返回':'双方已连接 · 每次行动自动保存';if(game.s.phase==='shop')message+=' · '+(snapshot.shopReady[seat]?'你已完成购物，等待对方':'双方完成购物后进入下一轮');if(game.s.phase==='deploy')message+=' · '+(snapshot.deployReady[seat]?'已锁定分路，等待对方确认':'双方确认前，分路安排互不可见');return `<div class="online-battle-status" role="status">${esc(message)}</div>`;},
 endHTML(g){return `<div class="phase-overlay"><section class="end-panel"><div class="eyebrow">MATCH COMPLETE</div><h2>${g.s.winner===2?'平局':watching?(g.s.winner===0?'天辉胜利':'夜魇胜利'):g.s.winner===0?'你获得了胜利':'本场落败'}</h2><p>对局结果已保存</p><div class="lobby-actions"><a class="primary" href="online.html">返回联机大厅</a><button class="secondary" data-action="log">查看战斗记录</button>${!watching?'<button class="secondary" data-action="copy-opponent-deck">保存对手构筑</button>':''}</div></section></div>`;},
 action(name,el,ctx){if(watching&&['confirm-surrender','surrender','finish-shop','finish-deploy','reset-deploy','unassign-deploy','assign-deploy','select-deploy','buy','hold','pass','play','activate','equip','use-skill'].includes(name)){ctx.toast('正在只读观战');return true;}if(['lobby','start','resume','decks','collection'].includes(name)){location.href='online.html';return true;}if(name==='save-match'){ctx.toast('联机对局已由服务器自动保存');return true;}if(name==='confirm-surrender'){document.querySelector('#modal')?.close();request('concede');return true;}if(name==='finish-shop'){if(!snapshot.shopReady[snapshot.seat])request('shopReady');else ctx.toast('已完成购物，等待对方');return true;}if(name==='finish-deploy'){if(bridge.deploymentLocked()){ctx.toast('已确认分路，等待对方');return true;}const plan=ctx.plan();if(!plan.complete){ctx.toast('请安排所有待回归英雄');return true;}request('deployReady',{assignments:plan.ready.map(u=>({uid:u.uid,lane:plan.lane(u.uid)}))});return true;}if(['reset-deploy','unassign-deploy','assign-deploy'].includes(name)&&bridge.deploymentLocked()){ctx.toast('分路已锁定，等待对方');return true;}if(['buy','hold'].includes(name)&&snapshot.shopReady[snapshot.seat]){ctx.toast('本轮已完成购物');return true;}return false;}
};
function renderWaiting(s){document.querySelector('#app').innerHTML=`<main class="boot"><h1>实时观战 · ${esc(s.code)}</h1><p>等待双方选好构筑并准备。观战不占玩家席位。</p><p>${s.players.map((p,i)=>`${i?'夜魇':'天辉'}：${p.ready?'已准备':p.occupied?'选择构筑中':'等待玩家'}`).join(' · ')}</p><a href="online.html">返回联机大厅</a></main>`;}
(async()=>{try{const code=new URLSearchParams(location.search).get('code')||net.lastCode();if(!code){location.replace('online.html');return;}snapshot=await net.connect(code,{spectate:watching});connected=true;if(watching&&!snapshot.state){renderWaiting(snapshot);await new Promise(resolve=>{const unsubscribe=net.subscribe(next=>{snapshot=next;renderWaiting(next);if(next.state){unsubscribe();resolve();}});});}if(!snapshot.state){location.replace('online.html?code='+encodeURIComponent(code));return;}game.s=project(snapshot.state,snapshot.seat);game.s.events=[];seen=snapshot.revision;for(const src of ['app.js?v=20260912-fx1','board-input.js?v=20260908-layout6','responsive-battle.js?v=20260909-watchtouch1','touch-cards.js?v=20260909-watchtouch1'])await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=src;script.onload=resolve;script.onerror=reject;document.body.appendChild(script);});}catch(e){document.querySelector('#app').innerHTML=`<main class="boot"><h1>暂时无法连接对局</h1><p>${esc(e.message||'请检查服务是否启动')}</p><a href="online.html">返回联机大厅重试</a></main>`;}})();
})(typeof window!=='undefined'?window:globalThis);
